<?php
require_once __DIR__ . '/auth.php';
require_once __DIR__ . '/../conexion.php';

function totalRows($db, $table) {
    try { return (int)$db->query("SELECT COUNT(*) FROM `$table`")->fetchColumn(); }
    catch (Throwable $e) { return null; }
}
function h($value) { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
$productsCount = totalRows($conexion, 'productos');
$usersCount = totalRows($conexion, 'usuarios');
$messagesCount = totalRows($conexion, 'contacto');
try { $recentProducts = $conexion->query('SELECT id,nombre,precio,stock,imagen FROM productos ORDER BY id DESC LIMIT 5')->fetchAll(); }
catch (Throwable $e) { $recentProducts = []; }
try { $recentMessages = $conexion->query('SELECT nombre,email,tipo_mensaje,mensaje FROM contacto ORDER BY id DESC LIMIT 4')->fetchAll(); }
catch (Throwable $e) { $recentMessages = []; }
$avatar = !empty($_SESSION['foto_perfil']) ? '../' . $_SESSION['foto_perfil'] : 'https://ui-avatars.com/api/?name=' . rawurlencode($_SESSION['usuario_nombre'] ?? 'Admin') . '&background=0876ea&color=fff&size=96';
?>
